"""Decision traces: generated by the tool, and the committed copies are current."""

from __future__ import annotations

import contextlib
import io

from reproduction.cli import TRACES, main
from reproduction.replay import replay_in_scratch
from reproduction.report import trace_document, trace_filename
from reproduction.scenarios import SCENARIOS, find
from tests.support import ScratchTestCase


class TraceTests(ScratchTestCase):
    def test_committed_traces_match_what_the_tool_generates(self):
        for scenario in SCENARIOS:
            with self.subTest(scenario=scenario.slug):
                run = replay_in_scratch(scenario)
                committed = (TRACES / trace_filename(run)).read_text(encoding="utf-8")
                self.assertEqual(trace_document(run), committed)

    def test_a_trace_states_what_was_seen_the_conditions_and_the_verdict(self):
        document = trace_document(replay_in_scratch(find("rename-changes-behaviour")))
        for expected in (
            "### What the gate saw",
            "### Conditions",
            "### Verdict: `RETIRE_INTERFACE_ONLY`",
            "| preserved |",
            "test_bulk_discount_starts_at_ten_units",
        ):
            self.assertIn(expected, document)

    def test_the_unlogged_trace_spells_out_the_question_for_a_human(self):
        document = trace_document(replay_in_scratch(find("unlogged-repair")))
        self.assertIn("**Scope decision needed from a human**", document)
        draft = "- rename shop.checkout.format_receipt to shop.receipts.format_receipt"
        self.assertIn(draft, document)


class CommandLineTests(ScratchTestCase):
    def run_cli(self, *argv: str) -> tuple[int, str]:
        output = io.StringIO()
        with contextlib.redirect_stdout(output):
            code = main(list(argv))
        return code, output.getvalue()

    def test_replaying_everything_writes_one_trace_per_scenario(self):
        code, output = self.run_cli("--traces", str(self.scratch))
        self.assertEqual(code, 0)
        self.assertEqual(len(list(self.scratch.glob("*.md"))), len(SCENARIOS))
        self.assertIn("rename-changes-behaviour  RETIRE_INTERFACE_ONLY", output)

    def test_one_scenario_can_be_printed_by_number_or_name(self):
        by_number = self.run_cli("3")
        by_name = self.run_cli("unlogged-repair")
        self.assertEqual(by_number, by_name)
        self.assertEqual(by_number[0], 0)
        self.assertIn("# Scenario 3: Honest repair nobody logged", by_number[1])

    def test_an_unknown_scenario_is_refused(self):
        with self.assertRaises(SystemExit), contextlib.redirect_stderr(io.StringIO()):
            main(["no-such-scenario"])
